# ttl_cache.py — a tiny TTL cache decorator with single-flight and jitter
import functools, random, threading, time
def ttl_cache(seconds: float, jitter: float = 0.1):
def decorate(fn):
store, locks, guard = {}, {}, threading.Lock() # args -> (value, expires_at)
@functools.wraps(fn)
def wrapper(*args):
hit = store.get(args)
if hit and hit[1] > time.monotonic():
return hit[0] # fresh hit, no locking
with guard:
lock = locks.setdefault(args, threading.Lock())
with lock: # single-flight: one caller recomputes
hit = store.get(args)
if hit and hit[1] > time.monotonic():
return hit[0] # another thread filled it meanwhile
value = fn(*args)
ttl = seconds * (1 + random.uniform(-jitter, jitter))
store[args] = (value, time.monotonic() + ttl)
return value
return wrapper
return decorate
calls = 0
@ttl_cache(seconds=2)
def load_profile(user_id: int) -> dict:
global calls
calls += 1
time.sleep(0.3) # slow database query
return {"id": user_id}
threads = [threading.Thread(target=load_profile, args=(7,)) for _ in range(50)]
for t in threads: t.start()
for t in threads: t.join()
print("50 concurrent callers, loads:", calls) # 1
Fifty threads, one database call. The double check inside the lock is what makes it work: whoever waited finds the fresh value that the first caller stored. (The store never shrinks; a real version would also evict old keys.)

Decorate a function that sleeps 0.3 s with functools.lru_cache, call it from 20 threads at once with the same argument, and count the calls. Then swap in ttl_cache(seconds=60) from Chapter 9.
Solution
import threading, time
from functools import lru_cache
n = 0
@lru_cache
def slow(x):
global n; n += 1; time.sleep(0.3); return x
ts = [threading.Thread(target=slow, args=(1,)) for _ in range(20)]
for t in ts: t.start()
for t in ts: t.join()
print(n) # 20: every thread missed before the first call finished
With @ttl_cache(seconds=60) instead of @lru_cache, n is 1: the other 19 threads wait on the per-key lock and then read the stored value.
